fn main() {
    let a = vec![1, 2];
    let b = a.clone();
    let c = a.clone();
    println!("{}", b.len());
    println!("{}", c.len());
}

fn main() {
    let s = String::from("ab");
    println!("{}", s.len());
    let mut total = 0;
    for _i in 0..3 {
        let t = s.clone();
        total += t.len();
    }
    println!("{}", total);
}

fn main() {
    let mut v = vec![1, 2];
    println!("{}", v.len());
    for x in &v {
        v.push(*x);
    }
    println!("{}", v.len());
}

fn main() {
