        let t = s.clone();
        println!("{}", t.len());
    }
    println!("{}", s.len());
}

fn main() {
    let v = vec![1, 2];
    let b = Bag { items: v.clone(), label: String::from("hello") };
    println!("{}", v.len());
    println!("{}", b.label.len());
}

fn size(o: Option<Vec<i32>>) -> usize {
    match o {
        Some(w) => w.len(),
        None => 0,
    }
}

fn main() {
    let v = vec![1, 2];
    let o = Some(v.clone());
    println!("{}", v.len());
    println!("{}", size(o));
}

fn main() {
    let s = String::from("hello");
    let v = vec![String::from("world"), s.clone()];
    println!("{}", v.len());
    println!("{}", s.len());
}

fn main() {
    let p = Point { x: 11, tag: String::from("hello") };
    let q = Point { x: 55, ..p.clone() }; // Clone p to avoid moving the value
    println!("{}", p.tag.len());
    println!("{}", q.x);
}

fn main() {
    let s = Pair { a: vec![1, 2], b: String::from("hello") };
    let Pair { a, ref b } = s;
    println!("{}", a.len());
    println!("{}", b.len());
    println!("{}", s.b.len());
}

fn main() {
    let o = Some(String::from("abcd"));
    match o {
        Some(ref s) => println!("{}", s.len() * 5),
        None => println!("0"),
    }
    match o.clone() {
        Some(s) => println!("{}", s.len() * 6),
        None => println!("0"),
    }
}

fn main() {
    let s = String::from("ab");
    println!("{}", s.len() * 10);
    let mut i = 0;
    let mut total = 0;
    while i < 3 {
        let t = s.clone();
        total += t.len() * 5;
        i += 1;
    }
    println!("{}", total);
}

fn total(v: Vec<i32>, flag: bool) -> usize {
    let w = v.clone();
    if flag {
        return w.len() * 10;
    }
    let mut u = v;
    u.push(3);
    u.len() * 20
}
fn main() {
    println!("{}", total(vec![1, 2], true));
    println!("{}", total(vec![1, 2], false));
}

fn f(o: Option<Vec<i32>>) -> Option<usize> {
    let v = o.clone()?;
    let w = o?;
    Some(v.len() * 10 + w.len())
}
fn main() {
    match f(Some(vec![1, 2])) {
        Some(n) => println!("{}", n),
        None => println!("0"),
    }
    match f(None) {
        Some(n) => println!("{}", n),
        None => println!("99"),
    }
}

fn main() {
    let s = String::from("hello");
    let n = 5;
    if n > 3 {
        if n > 4 {
            let t = s.clone();
            println!("{}", t.len() * 4);
        }
        println!("{}", s.len() * 6);
    }
}

fn push_back(v: &mut Vec<i32>, x: i32) -> &mut Vec<i32> {
    v.push(x);
    v
}
fn main() {
    let mut acc: Vec<i32> = (0..10).collect();
    println!("{}", acc.len());
    for i in 0..3 {
        push_back(&mut acc, i);
    }
    println!("{}", acc.len());
}

fn concat(a: &String, b: &String) -> String {
    format!("{}{}", a, b)
}
fn main() {
    let s = String::from("abcdefghij");
    println!("{}", s.len());
    let t = concat(&s, &s);
    println!("{}", t.len());
}

fn main() {
    let s = String::from("hello world");
    let n = 42;
    let t = s.clone();
    println!("{}", t.len());
    if n > 3 {
        println!("{}", s.len());
    }
}

fn push_back(mut v: Vec<i32>, x: i32) -> Vec<i32> {
    v.push(x);
    v
}

fn main() {
    let v: Vec<i32> = (0..10).collect();
    println!("{}", v.len());
    let mut total = 0;
    for x in &v.clone() {
        if *x > 4 {
            let w = push_back(v.clone(), *x);
            total = w.len();
            break;
        }
    }
    println!("{}", total);
}
